import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int len = inputStr.length();
        StringBuilder output = new StringBuilder();

        output.append(inputStr.charAt(0));
        int atReplaced = 0;
        int index = 1;

        while (index < len) {
            if (index != len - 3 && inputStr.startsWith("dot", index)) {
                output.append(".");
                index += 3;
            } else if (index != len - 2 && inputStr.startsWith("at", index) && atReplaced == 0) {
                output.append("@");
                index += 2;
                atReplaced = 1;
            } else {
                output.append(inputStr.charAt(index));
                index++;
            }
        }

        System.out.println(output.toString());
        scanner.close();
    }
}
